mapper.select:
SELECT r.ID_DESPACHO_DETALLE, r.CANTIDAD_ESTE_DESPACHO, r.CANTIDAD_ORIGINAL, r.CENTRO, r.CODIGO_MATERIAL, r.DESCRIPCION_MATERIAL, r.FECHA_ENTREGA_OC, r.ID_GUIA_DESPACHO, r.ID_ORDEN_DESPACHO_DETALLE, r.POSICION, r.UNIDAD_MEDIDA, r.DENOMINACION_CENTRO, r.NUMERO_ORDEN_DESPACHO, r.CANTIDAD_ENTREGADA_ANTERIOR FROM ( SELECT ggdd.ID_DESPACHO_DETALLE, ggdd.ID_ORDEN_DESPACHO_DETALLE, ggdd.CANTIDAD_ESTE_DESPACHO, ggdd.CANTIDAD_ORIGINAL, ggdd.CENTRO, ggdd.CODIGO_MATERIAL, ggdd.DESCRIPCION_MATERIAL, ggdd.FECHA_ENTREGA_OC, ggdd.ID_GUIA_DESPACHO, ggdd.POSICION, ggdd.UNIDAD_MEDIDA, ggdd.DENOMINACION_CENTRO, ggdd.NUMERO_ORDEN_DESPACHO, SUM( CASE WHEN ggd.ID_ESTADO_DESPACHO IN (1,5) THEN ggdd.CANTIDAD_ESTE_DESPACHO ELSE 0 END ) OVER ( PARTITION BY ggdd.NUMERO_ORDEN_DESPACHO, ggdd.POSICION ) AS CANTIDAD_ENTREGADA_ANTERIOR FROM GA_GUIA_DESPACHO_DETALLE ggdd INNER JOIN GA_GUIA_DESPACHO ggd ON ggd.ID_GUIA_DESPACHO = ggdd.ID_GUIA_DESPACHO ) r WHERE
r.ID_GUIA_DESPACHO = #{id}
ORDER BY r.POSICION ASC
